`StyleProperties` represents a small set of CSS-like properties. `mergeStyles(base, override)` must return a fresh object whose supplied override properties replace base properties. An omitted property leaves the base value unchanged. Values such as `0` and the empty string are valid overrides and must be preserved. Neither input may be mutated or returned by reference. An empty override produces an equal but fresh copy of base.

Known-bad source:

export interface StyleProperties {
  opacity?: number;
  marginInlineEnd?: number | string;
  display?: "block" | "none";
}

export function mergeStyles(base: StyleProperties, override: StyleProperties): StyleProperties {
  const result = { ...base };
  for (const key of Object.keys(override) as (keyof StyleProperties)[]) {
    const value = override[key];
    if (value) {
      Object.assign(result, { [key]: value });
    }
  }
  return result;
}

