import { mergeStyles } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(`${message}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}

const base = { opacity: 0.8, marginInlineEnd: '1rem', display: 'block' as const };
const override = { opacity: 0, marginInlineEnd: '', display: 'none' as const };
const merged = mergeStyles(base, override);
equal(merged, { opacity: 0, marginInlineEnd: '', display: 'none' }, 'falsy overrides must be preserved');
assert(merged !== base && merged !== override, 'result must be fresh');
equal(base, { opacity: 0.8, marginInlineEnd: '1rem', display: 'block' }, 'base must not mutate');
equal(override, { opacity: 0, marginInlineEnd: '', display: 'none' }, 'override must not mutate');

const partial = mergeStyles(base, { opacity: 0.25 });
equal(partial, { opacity: 0.25, marginInlineEnd: '1rem', display: 'block' }, 'omitted values retain base');

const empty1 = mergeStyles(base, {});
const empty2 = mergeStyles(base, {});
equal(empty1, base, 'empty override copies base');
assert(empty1 !== base && empty1 !== empty2, 'empty override results must be fresh');

empty1.opacity = 1;
assert(base.opacity === 0.8 && empty2.opacity === 0.8, 'result mutation must not leak');

const absent = mergeStyles({}, {});
equal(absent, {}, 'two empty styles');

